    Calibration steps
  </StageScreen>
);

import { Icon, Strong, UtilityScreen } from '@drizztdourden08/tessera';

interface UpdateCheckProps {
  notes: string;
  onClose: () => void;
  onInstall: () => void;
  onReport: () => void;
}

const UpdateCheck = ({ notes, onClose, onInstall, onReport }: UpdateCheckProps) => (
  <UtilityScreen
    title="Check for updates"
    onClose={onClose}
    status={{ tone: 'info', icon: <Icon name="download" />, title: 'Update available', message: <>Version <Strong>0.10.0</Strong> is available</> }}
    notes={{ title: 'What is new in 0.10.0', children: notes }}
    report={{ onClick: onReport }}
    actions={[
      { label: 'Later', variant: 'ghost', onClick: onClose },
      { label: 'Install', variant: 'primary', onClick: onInstall },
    ]}
  />
);

import { Icon, WorkspaceScreen } from '@drizztdourden08/tessera';
import type { WorkspaceContent } from '@drizztdourden08/tessera';

interface HubProps {
  volume: number;
  setVolume: (value: number) => void;
  onClose: () => void;
}

const SettingsHub = ({ volume, setVolume, onClose }: HubProps) => {
  const content: WorkspaceContent = {
    groups: [{
      id: 'app',
      label: 'App',
      pages: [{
        id: 'audio',
        title: 'Audio',
        icon: <Icon name="volume-2" />,
        sections: [{
          id: 'output',
          title: 'Output',
          rows: [{ id: 'volume', title: 'Master volume', description: 'The loudness of every sound.', hint: 'Drag or use the arrow keys.', input: { kind: 'slider', value: volume, onChange: setVolume, min: 0, max: 100 } }],
        }],
      }],
    }],
  };
  return <WorkspaceScreen title="Settings" onClose={onClose} content={content} />;
};
